                        if (is_buf)
                                p = strsep(&file, "\n");
                        else
                                p = fgets(string, OPT_LEN_MAX, f);
                        if (!p)
                                break;
                }

                skip_fgets = 0;
                strip_blank_front(&p);
                strip_blank_end(p);

                dprint(FD_PARSE, "%s\n", p);
                if (is_empty_or_comment(p))
