                                        "[] job section\n", p);
                                ret = 1;
                                break;
                        }

                        name[strlen(name) - 1] = '\0';

                        if (skip_this_section(name)) {
                                inside_skip = 1;
                                continue;
                        } else
                                inside_skip = 0;

