                                if (!global)
                                        log_info("--name=%s ", name);
                                first_sect = 0;
                        }

                        td = get_new_job(global, &def_thread, false, name);
                        if (!td) {
                                ret = 1;
                                break;
                        }

                        /*
                         * Separate multiple job files by a stonewall
                         */
                        if (!global && stonewall) {
                                td->o.stonewall = stonewall;
                                stonewall = 0;
                        }

                        num_opts = 0;
                        memset(opts, 0, alloc_opts * sizeof(char *));
                }
